#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Illuminance::new(v, IlluminanceUnit::Lux),
        Illuminance::from_lux(v)
    );
    assert_eq!(
        Illuminance::from_base(v).convert_to(IlluminanceUnit::Lux),
        Illuminance::from_base(v).as_lux()
    );
    assert_eq!(
        Illuminance::new(v, IlluminanceUnit::Millilux),
        Illuminance::from_millilux(v)
    );
    assert_eq!(
        Illuminance::from_base(v).convert_to(IlluminanceUnit::Millilux),
        Illuminance::from_base(v).as_millilux()
    );
    assert_eq!(
        Illuminance::new(v, IlluminanceUnit::Kilolux),
        Illuminance::from_kilolux(v)
    );
    assert_eq!(
        Illuminance::from_base(v).convert_to(IlluminanceUnit::Kilolux),
        Illuminance::from_base(v).as_kilolux()
    );
    assert_eq!(
        Illuminance::new(v, IlluminanceUnit::Megalux),
        Illuminance::from_megalux(v)
    );
    assert_eq!(
        Illuminance::from_base(v).convert_to(IlluminanceUnit::Megalux),
        Illuminance::from_base(v).as_megalux()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Illuminance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            Illuminance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in IlluminanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Illuminance::from_base(0.0).auto_unit().unit,
        IlluminanceUnit::Lux
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("lx".parse::<IlluminanceUnit>(), Ok(IlluminanceUnit::Lux));
    assert_eq!(
        format!("2.5 {}", "lx").parse::<Illuminance>(),
        Ok(Illuminance::new(2.5, IlluminanceUnit::Lux))
    );
    assert_eq!(
        "mlx".parse::<IlluminanceUnit>(),
        Ok(IlluminanceUnit::Millilux)
    );
    assert_eq!(
        format!("2.5 {}", "mlx").parse::<Illuminance>(),
        Ok(Illuminance::new(2.5, IlluminanceUnit::Millilux))
    );
    assert_eq!(
        "klx".parse::<IlluminanceUnit>(),
        Ok(IlluminanceUnit::Kilolux)
    );
    assert_eq!(
        format!("2.5 {}", "klx").parse::<Illuminance>(),
        Ok(Illuminance::new(2.5, IlluminanceUnit::Kilolux))
    );
    assert_eq!(
        "Mlx".parse::<IlluminanceUnit>(),
        Ok(IlluminanceUnit::Megalux)
    );
    assert_eq!(
        format!("2.5 {}", "Mlx").parse::<Illuminance>(),
        Ok(Illuminance::new(2.5, IlluminanceUnit::Megalux))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Illuminance>(),
        Err(ParseError::UnknownUnit)
    );
}

